from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *

# Cache/blocking tile sizes for the CPU. These are compile-time constants
# and can be tuned for a specific machine.
TI = 32   # tile size along i (rows of A, tmp, D)
TJ = 32   # tile size along j (cols of tmp, rows of B and C)
TK = 32   # tile size along k (cols of A, rows of B)
TL = 32   # tile size along l (cols of C, D)

@proc
def kernel_2mm(
    ni: size,
    nj: size,
    nk: size,
    nl: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    tmp: DATA_TYPE[ni, nj] @ DRAM,
    A: DATA_TYPE[ni, nk] @ DRAM,
    B: DATA_TYPE[nk, nj] @ DRAM,
    C: DATA_TYPE[nj, nl] @ DRAM,
    D: DATA_TYPE[ni, nl] @ DRAM,
):
    # Compute: D := alpha * A * B * C + beta * D
    #
    # Implemented as two GEMM-like stages:
    #   1) tmp = alpha * A * B      (ni x nj)
    #   2) D   = beta * D + tmp * C (ni x nl)
    #
    # We apply cache-aware tiling in all four dimensions. Within tiles:
    #   - Stage 1 uses i–k–j ordering so that A[i,k] is reused and
    #     B[k,j], tmp[i,j] are accessed with unit stride in j.
    #   - Stage 2 uses i–j–l ordering so that tmp[i,j] is reused and
    #     C[j,l], D[i,l] are accessed with unit stride in l.
    # This structure is friendly to the C compiler’s auto-vectorizer.

    # -------------------------
    # Stage 1: tmp = alpha * A * B
    # -------------------------
    # Outer tiles over i (rows of A/tmp) and j (cols of tmp / B).
    for I in seq(0, (ni + TI - 1) / TI):
        for J in seq(0, (nj + TJ - 1) / TJ):

            # 1a) Initialize the current tmp tile to zero:
            #       tmp[i, j] = 0.0
            # This is done once per (I, J) tile.
            for ii in seq(0, TI):
                if I * TI + ii < ni:
                    for jj in seq(0, TJ):
                        if J * TJ + jj < nj:
                            tmp[I * TI + ii, J * TJ + jj] = 0.0

            # 1b) Accumulate alpha * A * B into this tmp tile, tiled in k.
            # For each K tile we:
            #   - load and scale A[I*TI+ii, K*TK+kk] once into a_val
            #   - update all tmp[I*TI+ii, J*TJ+jj] in the J tile using
            #     contiguous B[K*TK+kk, J*TJ+jj].
            for K in seq(0, (nk + TK - 1) / TK):
                for ii in seq(0, TI):
                    if I * TI + ii < ni:
                        for kk in seq(0, TK):
                            if K * TK + kk < nk:
                                a_val: DATA_TYPE
                                a_val = alpha * A[I * TI + ii, K * TK + kk]
