    # Stage 2: D = beta * D + tmp * C
    # -------------------------
    # We first scale D by beta once per element, then add tmp * C.
    # Tiling over i and l keeps tiles of D and C in cache while reusing
    # tmp tiles across the shared j dimension.

    for I in seq(0, (ni + TI - 1) / TI):
        for L in seq(0, (nl + TL - 1) / TL):

            # 2a) Scale the D tile by beta:
            #       D[i, l] = beta * D[i, l]
            for ii in seq(0, TI):
                if I * TI + ii < ni:
                    for ll in seq(0, TL):
                        if L * TL + ll < nl:
                            D[I * TI + ii, L * TL + ll] = \
                                beta * D[I * TI + ii, L * TL + ll]

            # 2b) Accumulate tmp * C into the same D tile, j-tiled.
            # For each (I, L) tile and each J tile over j:
            #   - read tmp[I*TI+ii, J*TJ+jj] once into t_val
            #   - update all D[I*TI+ii, L*TL+ll] across ll with contiguous
            #     C[J*TJ+jj, L*TL+ll].
            for J in seq(0, (nj + TJ - 1) / TJ):
                for ii in seq(0, TI):
                    if I * TI + ii < ni:
                        for jj in seq(0, TJ):
                            if J * TJ + jj < nj:
                                t_val: DATA_TYPE
                                t_val = tmp[I * TI + ii, J * TJ + jj]
                                for ll in seq(0, TL):
                                    if L * TL + ll < nl:
                                        D[I * TI + ii, L * TL + ll] += \
                                            t_val * C[J * TJ + jj, L * TL + ll]
